import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller OwnerRestController (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api GET /api/owners/{ownerId}
 *
 * REST API 엔드포인트 GET /api/owners/{ownerId} 블랙박스 테스트
 * JWT Bearer 토큰 인증이 필수. 테스트는 owners 테이블에 테스트 데이터를 삽입하여 실행
 * 정상(200), 미존재(404), 잘못된 형식(400) 케이스 검증
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class OwnerGetOwnerBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "OWNER_ID", Long.toString(seq + 1000000000),
                "USERNAME", "user_" + testId(info),
                "FIRSTNAME", "TestFirst",
                "LASTNAME", "TestLast",
                "ADDRESS", "123 Test Street",
                "CITY", "TestCity",
                "PHONE", "5551234567");
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/owner-get-owner-teardown.sql", p);
        executeSqlTemplate("sql/owner-get-owner-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("\"{\\\"username\\\": \\\"admin\\\", \\\"password\\\": \\\"password\\\"}\"")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("token");
    }

    @Test
    void NTC_branch_getOwner_2(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("OWNER_ID"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("id", equalTo("${OWNER_ID}"))
                    .body("firstName", equalTo("TestFirst"))
                    .body("lastName", equalTo("TestLast"))
                    .body("address", equalTo("123 Test Street"))
                    .body("city", equalTo("TestCity"))
                    .body("telephone", equalTo("5551234567"))
                    .body("pets", notNullValue());
        } finally {
            executeSqlTemplate("sql/owner-get-owner-teardown.sql", p);
        }
    }

    @Test
    void ATC_ownerId_noData(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "999999999")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owner-get-owner-teardown.sql", p);
        }
    }

    @Test
    void ATC_code400(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "not_a_number")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-get-owner-teardown.sql", p);
        }
    }
}

